import{_ as s,C as n,o as l,c as d,a2 as a,j as o,E as r}from"./chunks/framework.B_GyVC5q.js";const y=JSON.parse('{"title":"Method Executor","description":"","frontmatter":{"title":"Method Executor"},"headers":[],"relativePath":"guide/method-executor.md","filePath":"guide/method-executor.md"}'),i={name:"guide/method-executor.md"};function h(c,e,u,p,g,m){const t=n("DocScreenshot");return l(),d("div",null,[e[0]||(e[0]=a('<h1 id="method-executor" tabindex="-1">Method Executor <a class="header-anchor" href="#method-executor" aria-label="Permalink to &quot;Method Executor&quot;">​</a></h1><p>Configure and run exposed 4D / ORDA methods from a dedicated tab. Open it from the <strong>command palette</strong>, dataclass and entity views, the <strong>Tools menu</strong>, or the assistant. <a href="/4d-dataexplorer/guide/parts.html#method-executor">Named parts</a>.</p><p>The left panel selects the method and arguments; the right panel shows the result.</p><h3 id="scopes" tabindex="-1">Scopes <a class="header-anchor" href="#scopes" aria-label="Permalink to &quot;Scopes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Scope</th><th>Expression</th><th>Use when</th></tr></thead><tbody><tr><td><strong>Datastore</strong></td><td><code>ds.method</code></td><td>Catalog / datastore functions</td></tr><tr><td><strong>Dataclass</strong></td><td><code>ds.Table.method</code></td><td>Class functions on a dataclass</td></tr><tr><td><strong>Entity</strong></td><td><code>ds.Table.entity(key).method</code></td><td>Methods on a single entity</td></tr><tr><td><strong>Entity selection</strong></td><td><code>ds.Table.sel(key).method</code></td><td>Methods on a server entity selection / entity set</td></tr></tbody></table><h3 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h3><p>Arguments keep positional order (<code>$1</code>, <code>$2</code>, …). Each can be a <strong>Custom</strong> value, an <strong>Entity</strong> reference, or an <strong>Entity selection</strong>. Reorder, duplicate, or remove them before execute.</p><h3 id="result-views" tabindex="-1">Result views <a class="header-anchor" href="#result-views" aria-label="Permalink to &quot;Result views&quot;">​</a></h3><p>After <strong>Execute</strong>, the right panel adapts to the response: an <strong>entity selection</strong> opens as a preview table (with count, <strong>Open all in new tab</strong>, and <a href="/4d-dataexplorer/guide/selection-tools.html">Selection tools</a>), a single <strong>entity</strong> opens in the entity viewer, and any other value is shown as read-only JSON. The screenshots below are examples from a sample database — the methods themselves are not built into the executor.</p><p>Enable <strong>Query plan &amp; path</strong> next to Execute to add <code>$queryplan</code> and <code>$querypath</code>. If the method response includes <code>__queryPlan</code> or <code>__queryPath</code>, a <strong>Plan</strong> tab appears beside Body / Headers with the same tree visualizer as the Query builder.</p>',10)),o("p",null,[r(t,{src:"/screenshots/19-method-executor-get-entity-sel.png",alt:"Entity selection result"})]),o("p",null,[r(t,{src:"/screenshots/20-method-executor-get-first-car.png",alt:"Entity result"})]),o("p",null,[r(t,{src:"/screenshots/21-method-executor-say-hello.png",alt:"JSON result"})]),e[1]||(e[1]=a('<h3 id="running-a-method" tabindex="-1">Running a method <a class="header-anchor" href="#running-a-method" aria-label="Permalink to &quot;Running a method&quot;">​</a></h3><ul><li>Defaults to a <strong>POST</strong> request. If the method allows HTTP GET, enable <strong>Execute with GET</strong>.</li><li>Click <strong>Execute</strong> when the target and arguments are complete.</li><li><strong>Copy as</strong> copies the REST call as runnable code in 4D, cURL, HTTP, JavaScript, Python, and other languages and libraries.</li><li><strong>History</strong> lists recent successful runs so you can reopen the same configuration. ⌘/Ctrl+click keys in history to open the related entity or selection.</li></ul><h3 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h3><p>Use <strong>Export</strong> to download the current method call (or favourites) as a <strong>Collection v2.1</strong> or <strong>OpenAPI 3.1</strong> document. For a full catalog toolkit, use <a href="/4d-dataexplorer/guide/rest-export.html">REST Export</a>.</p><h3 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h3><ul><li>Clear the current method with the <strong>×</strong> control to return to the catalog picker.</li><li>Incomplete entity / selection arguments block execution.</li><li>Entity-selection targets use the selection key (entity set ID); query filter / order-by from a data tab are not carried into the executor when an entity set is already bound.</li><li>From a <a href="/4d-dataexplorer/guide/flows.html">Flows</a> Method block, <strong>Open in Method Executor</strong> loads the same call in this tab.</li></ul>',6))])}const b=s(i,[["render",h]]);export{y as __pageData,b as default};
